const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'cover', index: 1, title: '1,001 Real-World Gen AI Use Cases from Google Cloud Customers' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Large accent shape top-right
  slide.addShape(pres.shapes.OVAL, {
    x: 6.5, y: -1.5, w: 5, h: 5,
    fill: { color: theme.secondary, transparency: 70 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 7.5, y: 3, w: 4, h: 4,
    fill: { color: theme.accent, transparency: 80 }
  });

  // Small label
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.7, y: 1.2, w: 2.4, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.15
  });
  slide.addText("GOOGLE CLOUD REPORT", {
    x: 0.7, y: 1.2, w: 2.4, h: 0.35,
    fontSize: 10, fontFace: "Calibri", bold: true,
    color: theme.primary, align: "center", valign: "middle"
  });

  // Main title
  slide.addText("1,001 Real-World\nGen AI Use Cases", {
    x: 0.7, y: 1.8, w: 7, h: 1.8,
    fontSize: 44, fontFace: "Georgia", bold: true,
    color: "FFFFFF", align: "left", valign: "top",
    lineSpacingMultiple: 1.1
  });

  // Subtitle
  slide.addText("From the World's Leading Organizations", {
    x: 0.7, y: 3.6, w: 6, h: 0.5,
    fontSize: 20, fontFace: "Calibri",
    color: theme.light, align: "left"
  });

  // Key stats row
  const stats = [
    { num: "1,001", label: "Use Cases" },
    { num: "11", label: "Industries" },
    { num: "6", label: "Agent Types" }
  ];
  stats.forEach((s, i) => {
    const sx = 0.7 + i * 2.2;
    slide.addText(s.num, {
      x: sx, y: 4.3, w: 1.8, h: 0.5,
      fontSize: 28, fontFace: "Georgia", bold: true,
      color: theme.accent, align: "left", margin: 0
    });
    slide.addText(s.label, {
      x: sx, y: 4.75, w: 1.8, h: 0.3,
      fontSize: 12, fontFace: "Calibri",
      color: theme.light, align: "left", margin: 0
    });
  });

  // Source line
  slide.addText("Source: Google Cloud Blog | Updated October 2025", {
    x: 0.7, y: 5.15, w: 5, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: theme.light
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

