const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 3, title: '11 Industries x 6 Agent Types: A Taxonomy of Enterprise Gen AI' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("11 Industries \u00D7 6 Agent Types: A Taxonomy of Enterprise Gen AI", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 24, fontFace: "Georgia", bold: true,
    color: theme.primary, align: "left", fit: "shrink"
  });

  const agents = ["Customer", "Employee", "Creative", "Code", "Data", "Security"];
  const industries = [
    "Automotive & Logistics",
    "Business & Professional Svcs",
    "Financial Services",
    "Healthcare & Life Sciences",
    "Hospitality & Travel",
    "Mfg, Industrial & Electronics",
    "Media, Marketing & Gaming",
    "Public Sector & Nonprofits",
    "Retail",
    "Technology",
    "Telecommunications"
  ];

  const startX = 0.5;
  const startY = 1.05;
  const labelW = 2.4;
  const colW = 1.13;
  const rowH = 0.345;
  const headerH = 0.45;

  // Agent type headers
  agents.forEach((a, i) => {
    const cx = startX + labelW + i * colW;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: startY, w: colW - 0.04, h: headerH,
      fill: { color: theme.primary }
    });
    slide.addText(a, {
      x: cx, y: startY, w: colW - 0.04, h: headerH,
      fontSize: 9, fontFace: "Calibri", bold: true,
      color: "FFFFFF", align: "center", valign: "middle"
    });
  });

  // Industry rows
  industries.forEach((ind, r) => {
    const ry = startY + headerH + 0.04 + r * (rowH + 0.04);
    const isEven = r % 2 === 0;

    // Row background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: startX, y: ry, w: labelW + colW * 6, h: rowH,
      fill: { color: isEven ? theme.light : "FFFFFF", transparency: isEven ? 70 : 0 }
    });

    // Industry label
    slide.addText(ind, {
      x: startX + 0.1, y: ry, w: labelW - 0.1, h: rowH,
      fontSize: 8.5, fontFace: "Calibri", bold: true,
      color: theme.primary, align: "left", valign: "middle"
    });

    // Dot indicators for each agent type
    agents.forEach((a, c) => {
      const cx = startX + labelW + c * colW + (colW - 0.04) / 2 - 0.08;
      slide.addShape(pres.shapes.OVAL, {
        x: cx, y: ry + rowH / 2 - 0.08, w: 0.16, h: 0.16,
        fill: { color: theme.secondary }
      });
    });
  });

  // Legend
  slide.addShape(pres.shapes.OVAL, {
    x: 0.5, y: 5.05, w: 0.14, h: 0.14,
    fill: { color: theme.secondary }
  });
  slide.addText("= Active use cases documented across the 1,001 deployments", {
    x: 0.72, y: 5.0, w: 5, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, align: "left", valign: "middle"
  });

  slide.addText("Framework organized by Google Cloud | Source: cloud.google.com", {
    x: 5.5, y: 5.0, w: 3.5, h: 0.25,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary, align: "right"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: "FFFFFF", align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

