const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 5, title: 'Quantified Impact: 500% ROI, 30% Workload Reduction, 10,000 Hours Saved' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addText("Quantified Impact: Production Results, Not Pilots", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Georgia", bold: true,
    color: "FFFFFF", align: "left"
  });

  const cards = [
    { metric: "500%", label: "Anticipated ROI", org: "Mercari", detail: "Japan\u2019s largest online marketplace, with 20% employee workload reduction through AI-powered customer service" },
    { metric: "30%", label: "Workload Reduction", org: "LUXGEN", detail: "Customer service agent workload reduced with Vertex AI chatbot on LINE platform" },
    { metric: "10,000+", label: "Man-Hours Saved/Year", org: "Toyota", detail: "Factory AI platform on Google Cloud enables workers to build and deploy ML models" },
    { metric: "6,000+", label: "Unique Headlines", org: "PODS / Tombras", detail: "Generated across 299 NYC neighborhoods in just 29 hours using Gemini" }
  ];

  const cardW = 4.25;
  const cardH = 1.7;
  const gap = 0.3;
  const startX = 0.5;
