const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 6, title: 'Common Patterns: Customer Assistants, Employee Productivity, and Creative Scale' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("Cross-Industry Patterns Across 1,001 Use Cases", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Georgia", bold: true,
    color: theme.primary, align: "left"
  });

  const patterns = [
    {
      num: "01",
      title: "Conversational Customer Agents",
      subtitle: "Most visible entry point",
      examples: "Mercedes-Benz, GM OnStar, Volkswagen, LUXGEN, Commerzbank, Mercari",
      detail: "AI-powered virtual assistants handle customer queries, reduce wait times, and lower human agent workloads across automotive, financial services, and retail."
    },
    {
      num: "02",
      title: "Employee Productivity Agents",
      subtitle: "Broadest category",
      examples: "Uber, Rivian, Geotab, Oxa",
      detail: "Gemini for Workspace summarizes documents, accelerates research, drafts content, reviews legal docs, and filters data across departments from HR to engineering."
    },
    {
      num: "03",
      title: "Creative & Scale Agents",
      subtitle: "Fastest-growing frontier",
      examples: "Virgin Voyages, PODS / Tombras, Figma",
      detail: "Hyper-personalized video campaigns, real-time adaptive billboards, and instant brand-approved asset generation \u2014 gen AI moves from text to multimodal creative at enterprise scale."
    }
  ];

  const colW = 2.85;
  const gap = 0.25;
  const startX = 0.5;
  const startY = 1.1;
  const cardH = 4.0;

  patterns.forEach((p, i) => {
    const cx = startX + i * (colW + gap);

    // Card
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: startY, w: colW, h: cardH,
      fill: { color: theme.light, transparency: 70 }
    });

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: cx + 0.2, y: startY + 0.2, w: 0.45, h: 0.45,
      fill: { color: theme.primary }
    });
    slide.addText(p.num, {
      x: cx + 0.2, y: startY + 0.2, w: 0.45, h: 0.45,
      fontSize: 14, fontFace: "Georgia", bold: true,
      color: "FFFFFF", align: "center", valign: "middle"
    });

    // Title
    slide.addText(p.title, {
      x: cx + 0.15, y: startY + 0.8, w: colW - 0.3, h: 0.55,
      fontSize: 14, fontFace: "Georgia", bold: true,
      color: theme.primary, align: "left", valign: "top"
    });

    // Subtitle tag
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: cx + 0.15, y: startY + 1.4, w: colW - 0.3, h: 0.25,
      fill: { color: theme.accent, transparency: 60 },
      rectRadius: 0.03
    });
    slide.addText(p.subtitle.toUpperCase(), {
      x: cx + 0.15, y: startY + 1.4, w: colW - 0.3, h: 0.25,
      fontSize: 8, fontFace: "Calibri", bold: true,
      color: theme.primary, align: "center", valign: "middle"
    });

    // Detail
    slide.addText(p.detail, {
      x: cx + 0.15, y: startY + 1.85, w: colW - 0.3, h: 1.1,
      fontSize: 10, fontFace: "Calibri",
      color: theme.primary, align: "left", valign: "top"
    });

    // Divider
    slide.addShape(pres.shapes.LINE, {
      x: cx + 0.15, y: startY + 3.05, w: colW - 0.3, h: 0,
      line: { color: theme.secondary, width: 0.5 }
    });

    // Examples label
    slide.addText("KEY PLAYERS", {
      x: cx + 0.15, y: startY + 3.15, w: colW - 0.3, h: 0.2,
      fontSize: 7, fontFace: "Calibri", bold: true,
      color: theme.secondary, align: "left"
    });
    slide.addText(p.examples, {
      x: cx + 0.15, y: startY + 3.35, w: colW - 0.3, h: 0.5,
      fontSize: 9, fontFace: "Calibri",
      color: theme.primary, align: "left", valign: "top"
    });
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: "FFFFFF", align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

