const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'summary', index: 7, title: 'Strategic Takeaways for Enterprise Leaders' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: theme.accent }
  });

  slide.addText("Strategic Takeaways for Enterprise Leaders", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Georgia", bold: true,
    color: theme.primary, align: "left"
  });

  const takeaways = [
    { num: "1", title: "Gen AI is production-ready across all major industries", detail: "1,001 use cases span 11 industries \u2014 from automotive to telecom, financial services to public sector. This is no longer experimental." },
    { num: "2", title: "Customer and employee agents are the most common entry points", detail: "Conversational assistants and workplace productivity tools dominate adoption patterns. Start here for fastest time-to-value." },
    { num: "3", title: "Measurable ROI is achievable within months", detail: "Organizations report 500% ROI (Mercari), 30% workload reduction (LUXGEN), 10,000+ hours saved (Toyota) \u2014 in production, not pilots." },
    { num: "4", title: "Creative and code agents are emerging fast", detail: "Virgin Voyages, Figma, PODS, and Renault show gen AI expanding beyond text into multimodal creative production and developer tools." },
    { num: "5", title: "The pace is accelerating \u2014 early movers gain compounding advantages", detail: "400 new entries in the latest update alone. Organizations deploying now build institutional knowledge that compounds over time." }
  ];

  const startY = 1.1;
  const rowH = 0.82;
  const gap = 0.1;

  takeaways.forEach((t, i) => {
    const ry = startY + i * (rowH + gap);

    // Number
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: ry + 0.08, w: 0.38, h: 0.38,
      fill: { color: theme.primary }
    });
    slide.addText(t.num, {
      x: 0.5, y: ry + 0.08, w: 0.38, h: 0.38,
      fontSize: 13, fontFace: "Georgia", bold: true,
      color: "FFFFFF", align: "center", valign: "middle"
    });

    // Title
    slide.addText(t.title, {
      x: 1.1, y: ry, w: 8.3, h: 0.32,
      fontSize: 13, fontFace: "Calibri", bold: true,
      color: theme.primary, align: "left", valign: "middle", margin: 0
    });

    // Detail
    slide.addText(t.detail, {
      x: 1.1, y: ry + 0.32, w: 8.3, h: 0.45,
      fontSize: 10, fontFace: "Calibri",
      color: theme.secondary, align: "left", valign: "top", margin: 0
    });
  });

  // Bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.35, w: 10, h: 0.28,
    fill: { color: theme.primary }
  });
  slide.addText("Source: Google Cloud Blog \u2014 \u201C1,001 real-world gen AI use cases\u201D | October 2025", {
    x: 0.5, y: 5.35, w: 8.5, h: 0.28,
    fontSize: 8, fontFace: "Calibri",
    color: "FFFFFF", align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: theme.primary, align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

